  public static void Reopen(string root){var goal=File.ReadAllText(Path.Combine(root,"goal.txt"));var store=new DesktopErgonProgressStore(root,"development");using(var w=store.AcquireWriter(new ProgressLockOwner())){var d=store.Inspect(w);var v=ProgressDomain.ManualWood(d,S,goal,"ok");Need(v.confirmedQuantity==200&&v.remainingQuantity==0&&v.receipts[0].confirmations.Length==2,"fresh-process history/total");}Console.WriteLine("PASS D2D10 new-process DPAPI quantity/history recovery");}
